-- ==========================================================================
-- B4 FOLLOW-ON FIX (dca): dca: one near-duplicate option
--
-- Courses: dca. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/dca.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql dca. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- dca intermediate final - ord 37
  select case when md5(prompt) = 'c4c9b2efeb1b047c250684536fa2cc34' and md5(coalesce(explanation, '')) = 'affac4c14e77cecd215302d5800afeba' and md5(options::text) = md5('["0.2 percent, so only a value carried to five decimals can pass", "20 percent, admitting the full-history Di", "2 percent, wide enough to admit any fit in the Excellent band", "2 percent, which is tight enough that a full-history fit fails the field"]'::jsonb::text) and answer_index = 3 then 'old'
              when md5(prompt) = 'c4c9b2efeb1b047c250684536fa2cc34' and md5(coalesce(explanation, '')) = 'affac4c14e77cecd215302d5800afeba' and md5(options::text) = md5('["0.2 percent, so only a value carried to five decimals can pass", "20 percent, admitting the full-history Di", "0.02 percent, reading 0.00002 straight off as a percentage", "2 percent, which is tight enough that a full-history fit fails the field"]'::jsonb::text) and answer_index = 3 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'dca' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null and ord = 37 and active;
  if v_state is null then raise exception 'B4 fix dca refused: no row for dca intermediate final - ord 37'; end if;
  if v_state = 'other' then raise exception 'B4 fix dca refused: dca intermediate final - ord 37 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'The capstone grades Ekene-6''s windowed Di of 0.001 per day to a tolerance of 0.00002. What fraction of the graded value is that?', options = '["0.2 percent, so only a value carried to five decimals can pass", "20 percent, admitting the full-history Di", "0.02 percent, reading 0.00002 straight off as a percentage", "2 percent, which is tight enough that a full-history fit fails the field"]'::jsonb,
           answer_index = 3, explanation = 'The tolerance is 2 percent of 0.001 per day. It is a window test rather than a precision test: fit the correct regime and any honest route lands inside it.'
     where app_slug = 'dca' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null and ord = 37 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix dca refused: dca intermediate final - ord 37 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'dca' and active;
  if v_total <> 396 then raise exception 'B4 fix dca refused: dca holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix dca: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
